class_name GameManager

const TILE_SIZE: int = 32
const GRID_WIDTH: int = 40
const GRID_HEIGHT: int = 22

var score: int = 0
var speed_level: int = 1
var arena_index: int = 0

var snake: Node = null
var orb_manager: Node = null
var ui: Node = null

var walls := {}

signal orb_eaten(new_score)

func _ready():
    _setup_input()
    _load_arena(arena_index)

    # Instantiate controllers
    snake = preload("res://game/scripts/snake_controller.gd").new()
    add_child(snake)
    snake.setup(self)
    snake.connect("ate_orb", Callable(self, "_on_snake_ate"))
    snake.connect("died", Callable(self, "_on_snake_died"))

    orb_manager = preload("res://game/scripts/orb_manager.gd").new()
    add_child(orb_manager)
    orb_manager.setup(self)
    orb_manager.spawn_orb()

    ui = preload("res://game/scripts/ui_controller.gd").new()
    add_child(ui)
    ui.setup(self)

    print("Neon Serpent: Game started")

func _setup_input() -> void:
    var actions = {
        "move_up": KEY_W,
        "move_down": KEY_S,
        "move_left": KEY_A,
        "move_right": KEY_D,
        "restart": KEY_R,
        "quit": KEY_ESCAPE
    }
    for name in actions.keys():
        if not InputMap.has_action(name):
            InputMap.add_action(name)
        var ev = InputEventKey.new()
        ev.physical_keycode = actions[name]
        InputMap.action_erase_events(name)
        InputMap.action_add_event(name, ev)

func _load_arena(index: int) -> void:
    walls.clear()
    for x in range(GRID_WIDTH):
        _set_wall(Vector2(x,0))
        _set_wall(Vector2(x,GRID_HEIGHT-1))
    for y in range(GRID_HEIGHT):
        _set_wall(Vector2(0,y))
        _set_wall(Vector2(GRID_WIDTH-1,y))
    if index == 1:
        var cx = int(GRID_WIDTH/2)
        for y in range(4, GRID_HEIGHT-4):
            _set_wall(Vector2(cx, y))
    elif index == 2:
        for x in range(6, 12):
            _set_wall(Vector2(x,6))
            _set_wall(Vector2(x,12))
        for y in range(6,13):
            _set_wall(Vector2(6,y))
            _set_wall(Vector2(11,y))

func _set_wall(cell: Vector2) -> void:
    walls["%d,%d" % [cell.x, cell.y]] = true

func is_cell_blocked(cell: Vector2) -> bool:
    if cell.x < 0 or cell.y < 0 or cell.x >= GRID_WIDTH or cell.y >= GRID_HEIGHT:
        return true
    return walls.has("%d,%d" % [cell.x, cell.y])

func get_random_free_cell() -> Vector2:
    var attempts = 0
    while attempts < 1000:
        var x = randi() % GRID_WIDTH
        var y = randi() % GRID_HEIGHT
        var c = Vector2(x,y)
        if not is_cell_blocked(c) and (snake == null or not snake.is_occupying_cell(c)) and not (orb_manager and orb_manager.has_orb_at(c)):
            return c
        attempts += 1
    return Vector2(1,1)

func register_orb_eaten() -> void:
    score += 10
    emit_signal("orb_eaten", score)
    var orbs_eaten = score / 10
    if orbs_eaten % 5 == 0:
        speed_level += 1
    if score >= 100:
        _on_win()

func _on_win() -> void:
    print("WIN")
    arena_index = (arena_index + 1) % 3
    _reset_for_new_arena()

func _on_snake_ate() -> void:
    register_orb_eaten()

func _on_snake_died(reason: String) -> void:
    on_snake_death(reason)

func on_snake_death(reason: String) -> void:
    print("GAME OVER")
    print("FINAL SCORE:%d" % score)
    if ui:
        ui.show_game_over()

func _reset_for_new_arena() -> void:
    score = 0
    speed_level = 1
    _load_arena(arena_index)
    if snake:
        snake.reset()
    if orb_manager:
        orb_manager.reset()
        orb_manager.spawn_orb()
    if ui:
        ui.update_score(score)
        ui.update_speed(speed_level)

func restart_current() -> void:
    score = 0
    speed_level = 1
    _load_arena(arena_index)
    if snake:
        snake.reset()
    if orb_manager:
        orb_manager.reset()
        orb_manager.spawn_orb()
    if ui:
        ui.update_score(score)
        ui.update_speed(speed_level)

func _process(delta: float) -> void:
    if snake:
        snake.set_speed_level(speed_level)
    if ui:
        ui.update_score(score)
        ui.update_speed(speed_level)
