{"path":"game/scripts/game_manager.gd","content":"extends Node2D
class_name GameManager

const TILE_SIZE: int = 32
const ARENA_TILES: Vector2 = Vector2(20,12) # width x height in tiles

var arena_index: int = 1
var score: int = 0
var orbs_eaten: int = 0
var speed_level: int = 1
var state: String = "init" # "playing", "gameover"

var snake_controller: Node = null
var orb_manager: Node = null
var ui: Node = null

onready var rng = RandomNumberGenerator.new()

func _ready() -> void:
    rng.randomize()
    # Input actions (add even if existing)
    InputMap.add_action("move_up")
    var e = InputEventKey.new()
    e.physical_scancode = Key.W
    InputMap.action_add_event("move_up", e)
    var e2 = InputEventKey.new()
    e2.physical_scancode = Key.UP
    InputMap.action_add_event("move_up", e2)

    InputMap.add_action("move_down")
    var ed = InputEventKey.new()
    ed.physical_scancode = Key.S
    InputMap.action_add_event("move_down", ed)
    var ed2 = InputEventKey.new()
    ed2.physical_scancode = Key.DOWN
    InputMap.action_add_event("move_down", ed2)

    InputMap.add_action("move_left")
    var el = InputEventKey.new()
    el.physical_scancode = Key.A
    InputMap.action_add_event("move_left", el)
    var el2 = InputEventKey.new()
    el2.physical_scancode = Key.LEFT
    InputMap.action_add_event("move_left", el2)

    InputMap.add_action("move_right")
    var er = InputEventKey.new()
    er.physical_scancode = Key.D
    InputMap.action_add_event("move_right", er)
    var er2 = InputEventKey.new()
    er2.physical_scancode = Key.RIGHT
    InputMap.action_add_event("move_right", er2)

    InputMap.add_action("restart")
    var rr = InputEventKey.new()
    rr.physical_scancode = Key.R
    InputMap.action_add_event("restart", rr)

    InputMap.add_action("quit")
    var rq = InputEventKey.new()
    rq.physical_scancode = Key.ESCAPE
    InputMap.action_add_event("quit", rq)

    # Load UI, snake and orb manager scenes (create them dynamically)
    _load_ui()
    _load_arena(arena_index)
    state = "playing"
    print("Neon Serpent")

func _load_ui() -> void:
    var ui_scene = preload("res://game/scenes/ui.tscn")
    ui = ui_scene.instantiate()
    add_child(ui)
    if ui and ui.has_method("setup"):
        ui.setup(self)
    _update_ui()

func _load_arena(index:int) -> void:
    # remove existing arena children (arenas named "ArenaRoot")
    for c in get_children():
        if c.name.begins_with("Arena_"):
            remove_child(c)
            c.queue_free()
    var path = "res://game/scenes/arena_%d.tscn" % index
    var scene = preload(path)
    var arena = scene.instantiate()
    arena.name = "Arena_%d" % index
    add_child(arena)
    # find walls nodes inside arena; arena should define Wall nodes under a node named "Walls" with children at grid positions
    # set up orb manager
    var orb_scene = preload("res://game/scripts/orb_manager.gd")
    # orb_manager is a script; instantiate a Node and attach the script
    var orb_manager_node = Node2D.new()
    orb_manager_node.name = "OrbManager"
    add_child(orb_manager_node)
    orb_manager = orb_manager_node
    orb_manager.set_script(preload("res://game/scripts/orb_manager.gd"))
    if orb_manager and orb_manager.has_method("setup"):
        orb_manager.setup(self)

    # Snake
    var snake_scene = preload("res://game/scenes/snake.tscn")
    var snake = snake_scene.instantiate()
    snake.name = "Snake"
    add_child(snake)
    snake_controller = snake
    if snake_controller and snake_controller.has_method("setup"):
        snake_controller.setup(self)
        snake_controller.connect("ate_orb", Callable(self, "_on_snake_ate_orb"))
        snake_controller.connect("died", Callable(self, "_on_snake_died"))

    # hazards: arena may export Position2D nodes under a node named "HazardSpawns"
    if arena.has_node("HazardSpawns"):
        var spawns = arena.get_node("HazardSpawns")
        for s in spawns.get_children():
            var hb_scene = preload("res://game/scenes/hazard_ball.tscn")
            var hb = hb_scene.instantiate()
            add_child(hb)
            if hb and hb.has_method("setup"):
                var vel = Vector2(rng.randf_range(-80,80), rng.randf_range(-80,80))
                hb.setup(self, vel)
                hb.global_position = s.global_position

    # initial orb spawn
    if orb_manager and orb_manager.has_method("spawn_orb"):
        orb_manager.spawn_orb()

func is_cell_blocked(cell: Vector2) -> bool:
    # check bounds
    if cell.x < 0 or cell.y < 0 or cell.x >= ARENA_TILES.x or cell.y >= ARENA_TILES.y:
        return true
    # check walls in current arena
    var arena = get_node_or_null("Arena_%d" % arena_index)
    if arena and arena.has_node("Walls"):
        var walls = arena.get_node("Walls")
        for w in walls.get_children():
            # walls placed at pixel positions; convert to grid
            var g = (w.position - Vector2(TILE_SIZE/2, TILE_SIZE/2)) / TILE_SIZE
            var gw = Vector2(round(g.x), round(g.y))
            if gw == cell:
                return true
    return false

func get_random_free_cell() -> Vector2:
    var tries = 0
    while tries < 200:
        var c = Vector2(rng.randi_range(0, ARENA_TILES.x - 1), rng.randi_range(0, ARENA_TILES.y - 1))
        if not is_cell_blocked(c) and (not snake_controller or not snake_controller.is_occupying_cell(c)) and (not orb_manager or not orb_manager.has_orb_at(c)):
            return c
        tries += 1
    return Vector2(0,0)

func register_orb_eaten() -> void:
    score += 10
    orbs_eaten += 1
    _update_ui()
    print("SCORE:%d" % score)
    if score >= 100:
        print("WIN")
        _advance_arena()
    if orbs_eaten % 5 == 0:
        speed_level += 1
        if snake_controller and snake_controller.has_method("set_speed_level"):
            snake_controller.set_speed_level(speed_level)
        _pulse_background()

func _pulse_background() -> void:
    # simple modulate pulse if a ColorRect named "Background" exists
    var bg = get_node_or_null("Background")
    if bg:
        bg.modulate = Color(0.8,0.8,1.0)
        bg.create_timer(0.15).connect("timeout", Callable(self, "_reset_background"))

func _reset_background() -> void:
    var bg = get_node_or_null("Background")
    if bg:
        bg.modulate = Color(1,1,1)

func on_snake_death(reason: String) -> void:
    if state == "gameover":
        return
    state = "gameover"
    # stop snake movement timer if present
    if snake_controller and snake_controller.has_method("move_timer"):
        # snake_controller stores timer in variable move_timer; try to stop it
        if has_node(snake_controller.get_path()):
            pass
    # try to stop timer directly
    if snake_controller and snake_controller.has_method("_on_move_timer"):
        # no direct stop API; rely on snake's move_timer property
        if snake_controller.move_timer:
            snake_controller.move_timer.stop()
    # show UI
    if ui and ui.has_method("show_game_over"):
        ui.show_game_over(score)
    print("GAME OVER %d" % score)

func _on_snake_ate_orb() -> void:
    # called when snake emits ate_orb; core growth handled by snake
    pass

func _on_snake_died(reason:String) -> void:
    on_snake_death(reason)

func _advance_arena() -> void:
    arena_index += 1
    if arena_index > 3:
        arena_index = 1
    # reload next arena
    _load_arena(arena_index)
    # reset score and state
    score = 0
    orbs_eaten = 0
    speed_level = 1
    _update_ui()

func restart_current_arena() -> void:
    # reset game state and objects in place
    state = "playing"
    score = 0
    orbs_eaten = 0
    speed_level = 1
    # reset snake
    if snake_controller and snake_controller.has_method("reset"):
        snake_controller.reset()
    # reset orb manager
    if orb_manager and orb_manager.has_method("reset"):
        orb_manager.reset()
    _update_ui()

func _update_ui() -> void:
    if ui and ui.has_method("update_score"):
        ui.update_score(score)
    if ui and ui.has_method("update_speed"):
        ui.update_speed(speed_level)

# exposure for hazard bounce
func get_arena_rect_pixels() -> Rect2:
    return Rect2(Vector2(0,0), ARENA_TILES * TILE_SIZE)

# convenience property
func _get_arena_rect_pixels():
    return get_arena_rect_pixels()

# input to handle restart/quit
func _process(delta: float) -> void:
    if state == "gameover":
        if Input.is_action_just_pressed("restart"):
            restart_current_arena()
        if Input.is_action_just_pressed("quit"):
            get_tree().quit()
","reason":"Implement GameManager core interfaces and state management required by other scripts."}

